INSERT INTO stories (slug, title_ar, summary_ar, content_ar, cover_emoji, age_group, read_time_min, level, pages, sort_order) VALUES
('my-red-ball', 'الْكُرَةُ الْحَمْرَاءُ', 'كُرَةٌ حَمْرَاءُ، وَصَدِيقٌ جَدِيدٌ، وَلَعِبٌ أَجْمَلُ.', '<p>عِنْدِي كُرَةٌ حَمْرَاءُ جَمِيلَةٌ. أَلْعَبُ بِهَا فِي الْحَدِيقَةِ كُلَّ يَوْمٍ. جَاءَ صَدِيقِي سَامِي، وَلَيْسَ مَعَهُ كُرَةٌ. قُلْتُ لَهُ: تَعَالَ نَلْعَبْ مَعًا! اللَّعِبُ مَعَ صَدِيقِي أَجْمَلُ مِنَ اللَّعِبِ وَحْدِي.</p>', '🔴', '3-5', 2, 1, '[{"text": "عِنْدِي كُرَةٌ حَمْرَاءُ جَمِيلَةٌ.", "scene": {"bg": "meadow", "items": [{"e": "🔴", "x": 50, "y": 60, "size": 120, "anim": "bounce"}]}}, {"text": "أَلْعَبُ بِهَا فِي الْحَدِيقَةِ كُلَّ يَوْمٍ.", "scene": {"bg": "garden", "items": [{"e": "👦", "x": 38, "y": 60, "size": 110, "anim": "sway"}, {"e": "🔴", "x": 64, "y": 72, "size": 50, "anim": "bounce"}]}}, {"text": "جَاءَ صَدِيقِي سَامِي، وَلَيْسَ مَعَهُ كُرَةٌ.", "scene": {"bg": "garden", "items": [{"e": "👦", "x": 30, "y": 60, "size": 100, "anim": "none"}, {"e": "🧒", "x": 70, "y": 60, "size": 100, "anim": "walk"}]}}, {"text": "قُلْتُ لَهُ: تَعَالَ نَلْعَبْ مَعًا!", "scene": {"bg": "meadow", "items": [{"e": "👦", "x": 30, "y": 60, "size": 100, "anim": "bounce"}, {"e": "🔴", "x": 50, "y": 50, "size": 50, "anim": "spin"}, {"e": "🧒", "x": 70, "y": 60, "size": 100, "anim": "bounce"}]}}, {"text": "اللَّعِبُ مَعَ صَدِيقِي أَجْمَلُ مِنَ اللَّعِبِ وَحْدِي.", "scene": {"bg": "sky", "items": [{"e": "👦", "x": 36, "y": 58, "size": 100, "anim": "sway"}, {"e": "🧒", "x": 64, "y": 58, "size": 100, "anim": "sway"}, {"e": "💛", "x": 50, "y": 28, "size": 50, "anim": "pulse"}]}}]'::jsonb, 110),
('bird-at-the-window', 'عُصْفُورٌ عَلَى الشُّبَّاكِ', 'لَيْلَى تُسَاعِدُ عُصْفُورًا عَطْشَانَ فِي يَوْمٍ حَارٍّ.', '<p>فِي يَوْمٍ حَارٍّ، وَقَفَ عُصْفُورٌ صَغِيرٌ عَلَى شُبَّاكِ لَيْلَى. كَانَ الْعُصْفُورُ مُتْعَبًا وَعَطْشَانَ. أَحْضَرَتْ لَيْلَى صَحْنًا صَغِيرًا فِيهِ مَاءٌ، وَوَضَعَتْهُ بِهُدُوءٍ. شَرِبَ الْعُصْفُورُ، ثُمَّ غَرَّدَ تَغْرِيدًا جَمِيلًا. طَارَ الْعُصْفُورُ إِلَى السَّمَاءِ، وَصَارَ يَزُورُ شُبَّاكَ لَيْلَى كُلَّ صَبَاحٍ.</p>', '🐦', '6-8', 3, 2, '[{"text": "فِي يَوْمٍ حَارٍّ، وَقَفَ عُصْفُورٌ صَغِيرٌ عَلَى شُبَّاكِ لَيْلَى.", "scene": {"bg": "home", "items": [{"e": "🐦", "x": 70, "y": 40, "size": 70, "anim": "sway"}, {"e": "👧", "x": 34, "y": 62, "size": 100, "anim": "none"}]}}, {"text": "كَانَ الْعُصْفُورُ مُتْعَبًا وَعَطْشَانَ.", "scene": {"bg": "desert", "items": [{"e": "🐦", "x": 50, "y": 55, "size": 90, "anim": "pulse"}]}}, {"text": "أَحْضَرَتْ لَيْلَى صَحْنًا صَغِيرًا فِيهِ مَاءٌ، وَوَضَعَتْهُ بِهُدُوءٍ.", "scene": {"bg": "home", "items": [{"e": "👧", "x": 34, "y": 60, "size": 100, "anim": "sway"}, {"e": "💧", "x": 62, "y": 66, "size": 50, "anim": "bounce"}]}}, {"text": "شَرِبَ الْعُصْفُورُ، ثُمَّ غَرَّدَ تَغْرِيدًا جَمِيلًا.", "scene": {"bg": "garden", "items": [{"e": "🐦", "x": 50, "y": 50, "size": 90, "anim": "bounce"}, {"e": "🎵", "x": 68, "y": 30, "size": 44, "anim": "float"}]}}, {"text": "طَارَ الْعُصْفُورُ إِلَى السَّمَاءِ، وَصَارَ يَزُورُ شُبَّاكَ لَيْلَى كُلَّ صَبَاحٍ.", "scene": {"bg": "sky", "items": [{"e": "🐦", "x": 50, "y": 40, "size": 80, "anim": "float"}, {"e": "👧", "x": 30, "y": 72, "size": 80, "anim": "sway"}]}}]'::jsonb, 111),
('vegetable-market', 'سوق الخضار', 'منى تساعد أمها في السوق وتكتشف أن الحساب مفيد في كل مكان.', '<p>في صباح يوم الجمعة، ذهبت منى مع أمها إلى سوق الخضار. كان السوق مليئًا بالألوان: طماطم حمراء، وخيار أخضر، وجزر برتقالي. قالت الأم: نحتاج إلى كيلو طماطم وكيلو خيار. هل تساعدينني في الحساب؟ كان ثمن كيلو الطماطم عشرة جنيهات، وكيلو الخيار ثمانية جنيهات. فكرت منى قليلًا ثم قالت: المجموع ثمانية عشر جنيهًا! ابتسم البائع وقال: أحسنتِ يا منى! وأعطاها تفاحة هدية. في طريق العودة قالت منى: شكرًا يا أمي، تعلمت اليوم أن الحساب مفيد في كل مكان.</p>', '🧺', '6-8', 4, 3, '[{"text": "في صباح يوم الجمعة، ذهبت منى مع أمها إلى سوق الخضار.", "scene": {"bg": "village", "items": [{"e": "👧", "x": 36, "y": 64, "size": 90, "anim": "walk"}, {"e": "👩", "x": 58, "y": 60, "size": 100, "anim": "none"}]}}, {"text": "كان السوق مليئًا بالألوان: طماطم حمراء، وخيار أخضر، وجزر برتقالي.", "scene": {"bg": "village", "items": [{"e": "🍅", "x": 30, "y": 66, "size": 60, "anim": "bounce"}, {"e": "🥒", "x": 50, "y": 66, "size": 60, "anim": "bounce"}, {"e": "🥕", "x": 70, "y": 66, "size": 60, "anim": "bounce"}]}}, {"text": "قالت الأم: نحتاج إلى كيلو طماطم وكيلو خيار. هل تساعدينني في الحساب؟", "scene": {"bg": "village", "items": [{"e": "👩", "x": 60, "y": 58, "size": 100, "anim": "sway"}, {"e": "👧", "x": 34, "y": 64, "size": 90, "anim": "none"}]}}, {"text": "كان ثمن كيلو الطماطم عشرة جنيهات، وكيلو الخيار ثمانية جنيهات. فكرت منى قليلًا ثم قالت: المجموع ثمانية عشر جنيهًا!", "scene": {"bg": "village", "items": [{"e": "🍅", "x": 30, "y": 50, "size": 54, "anim": "none"}, {"e": "➕", "x": 45, "y": 50, "size": 40, "anim": "pulse"}, {"e": "🥒", "x": 60, "y": 50, "size": 54, "anim": "none"}, {"e": "👧", "x": 50, "y": 76, "size": 70, "anim": "bounce"}]}}, {"text": "ابتسم البائع وقال: أحسنتِ يا منى! وأعطاها تفاحة هدية.", "scene": {"bg": "village", "items": [{"e": "👨", "x": 64, "y": 58, "size": 100, "anim": "sway"}, {"e": "🍎", "x": 46, "y": 50, "size": 50, "anim": "bounce"}, {"e": "👧", "x": 30, "y": 64, "size": 90, "anim": "bounce"}]}}, {"text": "في طريق العودة قالت منى: شكرًا يا أمي، تعلمت اليوم أن الحساب مفيد في كل مكان.", "scene": {"bg": "meadow", "items": [{"e": "👧", "x": 40, "y": 62, "size": 90, "anim": "walk"}, {"e": "👩", "x": 62, "y": 60, "size": 100, "anim": "walk"}, {"e": "🧺", "x": 72, "y": 74, "size": 44, "anim": "none"}]}}]'::jsonb, 112),
('turtle-and-the-bag', 'السلحفاة والكيس', 'كريم يرى سلحفاة بحرية عالقة، ويعرف كيف يساعدها بالطريقة الصحيحة.', '<p>في الإجازة الصيفية سافر كريم مع أسرته إلى مرسى علم على شاطئ البحر الأحمر. وبينما كان يسبح قرب الشاطئ، رأى سلحفاة بحرية تتحرك بصعوبة، فقد علق كيس بلاستيكي حول زعنفتها. تذكر كريم ما تعلمه في المدرسة: لا نلمس الحيوانات البرية بأنفسنا، بل نطلب المساعدة من المختصين. أسرع إلى حارس الشاطئ وأخبره، فجاء الحارس ومعه فريق حماية البيئة، وحرروا السلحفاة برفق. سبحت السلحفاة مبتعدة في الماء الأزرق، ولوّح لها كريم فرحًا. قال الحارس: الكيس الذي نرميه قد يصل إلى البحر ويؤذي كائنات كثيرة. ومنذ ذلك اليوم صار كريم يجمع البلاستيك من الشاطئ ويضعه في سلة المهملات.</p>', '🐢', '9-12', 5, 4, '[{"text": "في الإجازة الصيفية سافر كريم مع أسرته إلى مرسى علم على شاطئ البحر الأحمر.", "scene": {"bg": "sea", "items": [{"e": "👦", "x": 30, "y": 46, "size": 80, "anim": "bounce"}, {"e": "🐚", "x": 70, "y": 50, "size": 44, "anim": "none"}]}}, {"text": "وبينما كان يسبح قرب الشاطئ، رأى سلحفاة بحرية تتحرك بصعوبة، فقد علق كيس بلاستيكي حول زعنفتها.", "scene": {"bg": "sea", "items": [{"e": "🐢", "x": 50, "y": 72, "size": 90, "anim": "sway"}, {"e": "🛍️", "x": 62, "y": 66, "size": 40, "anim": "float"}]}}, {"text": "تذكر كريم ما تعلمه في المدرسة: لا نلمس الحيوانات البرية بأنفسنا، بل نطلب المساعدة من المختصين.", "scene": {"bg": "sea", "items": [{"e": "👦", "x": 40, "y": 46, "size": 90, "anim": "pulse"}, {"e": "💭", "x": 60, "y": 24, "size": 50, "anim": "float"}]}}, {"text": "أسرع إلى حارس الشاطئ وأخبره، فجاء الحارس ومعه فريق حماية البيئة، وحرروا السلحفاة برفق.", "scene": {"bg": "sea", "items": [{"e": "👦", "x": 26, "y": 46, "size": 70, "anim": "walk"}, {"e": "👮", "x": 50, "y": 46, "size": 80, "anim": "none"}, {"e": "🐢", "x": 72, "y": 72, "size": 70, "anim": "sway"}]}}, {"text": "سبحت السلحفاة مبتعدة في الماء الأزرق، ولوّح لها كريم فرحًا.", "scene": {"bg": "sea", "items": [{"e": "🐢", "x": 64, "y": 74, "size": 80, "anim": "walk"}, {"e": "👋", "x": 30, "y": 46, "size": 60, "anim": "sway"}]}}, {"text": "قال الحارس: الكيس الذي نرميه قد يصل إلى البحر ويؤذي كائنات كثيرة. ومنذ ذلك اليوم صار كريم يجمع البلاستيك من الشاطئ ويضعه في سلة المهملات.", "scene": {"bg": "sea", "items": [{"e": "👦", "x": 36, "y": 46, "size": 80, "anim": "bounce"}, {"e": "♻️", "x": 62, "y": 40, "size": 60, "anim": "spin"}]}}]'::jsonb, 113)
